import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    """
    Extract matches from all text files in a directory.

    Special default behavior:
    - Text inside parentheses is returned as one match, without the parentheses.
    - Any character outside parentheses is returned as an individual match.
    """
    results = {}
    base_dir = Path(directory_path)

    if not base_dir.exists() or not base_dir.is_dir():
        return results

    # The prompt's default regex is escaped in the supplied context; support both forms.
    special_default_patterns = {
        r'\\(.+?\\)|\\w',
        r'\(.+?\)|\w',
    }

    if regex_pattern in special_default_patterns:
        token_re = re.compile(r'\(([^()]*)\)|[\s\S]')

    for file_path in sorted(glob.glob(os.path.join(directory_path, "*"))):
        path = Path(file_path)
        if not path.is_file():
            continue

        try:
            content = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        if regex_pattern in special_default_patterns:
            matches = []
            for match in token_re.finditer(content):
                parenthesized = match.group(1)
                matches.append(parenthesized if parenthesized is not None else match.group(0))
        else:
            matches = [m.group(0) for m in re.finditer(regex_pattern, content)]

        results[path.name] = matches

    return results

import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt


def task_func(s1, s2):
    def _to_series(obj):
        if isinstance(obj, pd.Series):
            return obj.copy()
        if isinstance(obj, (str, bytes)):
            return pd.Series([obj])
        try:
            return pd.Series(obj)
        except Exception:
            return pd.Series([obj])

    def _label(obj, default):
        if isinstance(obj, pd.Series) and obj.name not in (None, ""):
            return str(obj.name)
        return default

    s1 = _to_series(s1)
    s2 = _to_series(s2)

    s1_non_null = s1.dropna()
    s2_non_null = s2.dropna()

    common_values = s1_non_null[s1_non_null.isin(s2_non_null)].drop_duplicates().tolist()
    intersection_count = len(common_values)

    label1 = _label(s1, "Series 1")
    label2 = _label(s2, "Series 2")

    values = pd.concat([s1, s2], ignore_index=True)
    series_labels = [label1] * len(s1) + [label2] * len(s2)
    plot_df = pd.DataFrame({"Series": series_labels, "Value": values}).dropna(subset=["Value"])

    fig, ax = plt.subplots()
    sns.swarmplot(data=plot_df, x="Series", y="Value", ax=ax)

    for idx, value in enumerate(common_values):
        ax.axhline(
            y=value,
            color="red",
            linestyle="--",
            linewidth=1,
            alpha=0.7,
            label="Intersection" if idx == 0 else None,
        )

    ax.set_xlabel("")
    ax.set_ylabel("Value")
    ax.set_title("Swarm Plot Comparison")

    if common_values:
        ax.legend()

    return ax, intersection_count

import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    temp_path = f"{save_path}.tmp"
    final_zip_created = False

    try:
        save_dir = os.path.dirname(os.path.abspath(save_path))
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)
        os.makedirs(extract_path, exist_ok=True)

        try:
            with urllib.request.urlopen(url) as response, open(temp_path, "wb") as out_file:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
        except urllib.error.URLError as e:
            reason = getattr(e, "reason", e)
            return f"URL Error: {reason}"
        except ValueError as e:
            return f"URL Error: {e}"

        try:
            os.replace(temp_path, save_path)
            final_zip_created = True
        except OSError as e:
            return f"File I/O Error: {e}"

        try:
            with zipfile.ZipFile(save_path, "r") as zip_ref:
                zip_ref.extractall(extract_path)
        except zipfile.BadZipFile as e:
            return f"ZIP Error: {e}"
        except zipfile.LargeZipFile as e:
            return f"ZIP Error: {e}"
        except OSError as e:
            return f"File I/O Error: {e}"

        return extract_path

    except OSError as e:
        return f"File I/O Error: {e}"

    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass

        if final_zip_created and os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError:
                pass

import pandas as pd
import json
import os
import shutil

def task_func(path):
    os.makedirs(path, exist_ok=True)
    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    frames = []

    json_files = sorted(
        name for name in os.listdir(path)
        if os.path.isfile(os.path.join(path, name)) and name.lower().endswith(".json")
    )

    for filename in json_files:
        file_path = os.path.join(path, filename)

        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)

        if isinstance(data, list):
            df = pd.DataFrame(data)
        elif isinstance(data, dict):
            # Handle either a single JSON object or a dict of column arrays.
            if data and all(isinstance(v, list) for v in data.values()):
                df = pd.DataFrame(data)
            else:
                df = pd.DataFrame([data])
        else:
            df = pd.DataFrame([{"value": data}])

        if "Source" in df.columns:
            df["Source"] = filename
            df = df[["Source"] + [c for c in df.columns if c != "Source"]]
        else:
            df.insert(0, "Source", filename)

        frames.append(df)

        dest_path = os.path.join(processed_dir, filename)
        if os.path.exists(dest_path):
            if os.path.isdir(dest_path):
                shutil.rmtree(dest_path)
            else:
                os.remove(dest_path)
        shutil.move(file_path, dest_path)

    if frames:
        return pd.concat(frames, ignore_index=True, sort=False)

    return pd.DataFrame()

