import os
from openpyxl import load_workbook


def task_func(directory_path='./xlsx_files/'):
    def _escape_quotes(text):
        return re.sub(r'"', lambda _: r'\\"', text)

    processed_files = 0
    file_paths = []

    if os.path.isfile(directory_path):
        if directory_path.lower().endswith('.xlsx'):
            file_paths = [directory_path]
    elif os.path.isdir(directory_path):
        file_paths = glob.glob(os.path.join(directory_path, '*.xlsx'))
        file_paths += glob.glob(os.path.join(directory_path, '*.XLSX'))

    for file_path in sorted(set(file_paths)):
        try:
            workbook = load_workbook(file_path)
            changed = False

            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        value = cell.value
                        if isinstance(value, str) and cell.data_type != 'f' and '"' in value:
                            new_value = _escape_quotes(value)
                            if new_value != value:
                                cell.value = new_value
                                changed = True

            if changed:
                workbook.save(file_path)

            processed_files += 1
        except Exception:
            continue

    return processed_files

import os
