import pandas as pd
import docx


SUPPORTED_EXTENSIONS = {".txt", ".docx", ".xlsx", ".csv"}


def _extract_text_from_txt_or_csv(file_path: Path) -> str:
    return file_path.read_text(encoding="utf-8", errors="replace")


def _extract_text_from_docx(file_path: Path) -> str:
    document = docx.Document(str(file_path))
    chunks = []

    for paragraph in document.paragraphs:
        text = paragraph.text.strip()
        if text:
            chunks.append(text)

    for table in document.tables:
        for row in table.rows:
            row_text = "\t".join(
                cell.text.strip() for cell in row.cells if cell.text and cell.text.strip()
            )
            if row_text:
                chunks.append(row_text)

    return "\n".join(chunks)


def _extract_text_from_xlsx(file_path: Path) -> str:
    workbook = pd.read_excel(file_path, sheet_name=None, header=None, dtype=object)
    sheet_chunks = []

    for sheet_df in workbook.values():
        if sheet_df is None or sheet_df.empty:
            continue
        sheet_text = sheet_df.fillna("").to_csv(index=False, header=False)
        sheet_text = sheet_text.rstrip("\n")
        if sheet_text:
            sheet_chunks.append(sheet_text)

    return "\n\n".join(sheet_chunks)


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    if not source_path.exists() or not source_path.is_dir():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")

    target_path = Path(target_directory)
    target_path.mkdir(parents=True, exist_ok=True)

    source_files = sorted(
        (path for path in source_path.iterdir() if path.is_file()),
        key=lambda path: path.name.lower(),
    )

    converted_count = 0

    for file_path in source_files:
        extension = file_path.suffix.lower()
        if extension not in SUPPORTED_EXTENSIONS:
            continue

        if extension in {".txt", ".csv"}:
            text_content = _extract_text_from_txt_or_csv(file_path)
        elif extension == ".docx":
            text_content = _extract_text_from_docx(file_path)
        else:  # .xlsx
            text_content = _extract_text_from_xlsx(file_path)

        output_path = target_path / f"{file_path.stem}.csv"
        pd.DataFrame({"Text": [text_content]}).to_csv(output_path, index=False)
        converted_count += 1

    return converted_count

